frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

$(document).ready(function () {

    // =========================================================================
    //  CONFIG
    // =========================================================================

    var DRAFT_KEY_PREFIX = 'fle_draft_v4_';  // per-user key prefix

    // =========================================================================
    //  USER IDENTITY  — identifies whose draft this is
    //  Sources (in priority order):
    //    1. URL query param  ?email_address=...
    //    2. DOM email field (may not exist yet at boot — re-checked on save/restore)
    //    3. Frappe session user (frappe.session.user)
    // =========================================================================

    function getUserEmail() {
        // 1. URL query param — most reliable, set by Frappe when opening the form
        var params = new URLSearchParams(window.location.search);
        var urlEmail = params.get('email_address') || params.get('email') || '';
        if (urlEmail && urlEmail.indexOf('@') !== -1) return urlEmail.toLowerCase().trim();

        // 2. DOM email field — available after Frappe renders the form
        var emailWrapper = document.querySelector('[data-fieldname="email_address"]');
        if (emailWrapper) {
            var emailInp = emailWrapper.querySelector('input.input-with-feedback');
            if (emailInp && emailInp.value && emailInp.value.indexOf('@') !== -1) {
                return emailInp.value.toLowerCase().trim();
            }
        }

        // 3. Frappe session (logged-in user)
        if (window.frappe && frappe.session && frappe.session.user &&
            frappe.session.user !== 'Guest') {
            return frappe.session.user.toLowerCase().trim();
        }

        return '';  // anonymous — no user-specific key available yet
    }

    function getDraftKey() {
        var email = getUserEmail();
        if (!email) return null;  // cannot generate a safe key without identity
        // Sanitise email for use as a localStorage key
        return DRAFT_KEY_PREFIX + email.replace(/[^a-z0-9@._-]/g, '_');
    }

    // Explicit field types:
    //   'select' = Frappe Select  (hidden <select> + display input, fixed options)
    //   'link'   = Frappe Link    (autocomplete against a DocType — Nationality etc.)
    //   'check'  = Frappe Check   (checkbox)
    //   'text'   = everything else (Data, Date, Int, Phone, Email, Textarea)
    var TYPED_FIELDS = {
        'candidate_gender'               : 'select',
        'candidate_state'                : 'select',
        'where_did_you_hear'             : 'select',
        'last_class_attended'            : 'select',
        'latest_board_attended'          : 'select',
        'year_of_passing'                : 'select',
        'relationship_with_the_candidate': 'select',
        'candidate_nationality'          : 'link',
        'i_hereby_consent_to_this_declaration': 'check'
    };

    // System fields to never save
    var SKIP_FIELDS = { '__newname': true, 'amended_from': true };

    // Required fields for "Proceed to Pay" button visibility
    var REQUIRED_FOR_PAY = [
        'email_address', 'candidate_name', 'candidate_dob',
        'candidate_gender', 'where_did_you_hear',
        'last_class_attended', 'latest_board_attended', 'year_of_passing'
    ];

    // =========================================================================
    //  STORAGE  — localStorage persists across reloads
    // =========================================================================

    var Store = {
        save: function (data) {
            var key = getDraftKey();
            if (!key) { console.warn('[Draft] No user key — cannot save.'); return false; }
            try { localStorage.setItem(key, JSON.stringify(data)); return true; }
            catch (e) { console.error('[Draft] save error:', e); return false; }
        },
        load: function () {
            var key = getDraftKey();
            if (!key) return null;
            try { var r = localStorage.getItem(key); return r ? JSON.parse(r) : null; }
            catch (e) { return null; }
        },
        // Remove drafts belonging to OTHER users for this form (cleanup)
        clearOtherUsers: function (currentEmail) {
            if (!currentEmail) return;
            var currentKey = DRAFT_KEY_PREFIX + currentEmail.replace(/[^a-z0-9@._-]/g, '_');
            Object.keys(localStorage).forEach(function (k) {
                if (k.indexOf(DRAFT_KEY_PREFIX) === 0 && k !== currentKey) {
                    // Different user's draft on same browser — leave it (other user may return)
                    // Only clear if it's the exact same form prefix to be safe
                }
            });
        }
    };

    // =========================================================================
    //  FIELD DISCOVERY  — scans live DOM, handles all Frappe field types
    // =========================================================================

    function discoverFields() {
        var result = [], seen = {};

        document.querySelectorAll('[data-fieldname]').forEach(function (wrapper) {
            var fn = wrapper.getAttribute('data-fieldname');
            if (!fn || seen[fn] || SKIP_FIELDS[fn]) return;

            // Determine type
            var explicitType = TYPED_FIELDS[fn];

            // Detect checkbox
            var chk = wrapper.querySelector('input[type="checkbox"]');
            if (!explicitType && chk) explicitType = 'check';

            // Must have a real input/select/textarea/checkbox
            var hasInput = wrapper.querySelector(
                'input.input-with-feedback, select, textarea, input[type="checkbox"]'
            );
            if (!hasInput) return;

            seen[fn] = true;
            result.push({ fieldname: fn, type: explicitType || 'text' });
        });

        return result;
    }

    // =========================================================================
    //  READ  — get the true committed value from the DOM
    // =========================================================================

    function readField(cfg) {
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return '';

        // ── Checkbox ──────────────────────────────────────────────────────────
        if (cfg.type === 'check') {
            var chk = wrapper.querySelector('input[type="checkbox"]');
            return chk ? (chk.checked ? '1' : '0') : '';
        }

        // ── Frappe Select (fixed option list) ────────────────────────────────
        if (cfg.type === 'select') {
            var sel = wrapper.querySelector('select');
            if (sel && sel.value && sel.value.trim()) return sel.value.trim();
            var inp = wrapper.querySelector('input.input-with-feedback');
            if (inp && inp.value && inp.value.trim()) return inp.value.trim();
            return '';
        }

        // ── Frappe Link (autocomplete) ────────────────────────────────────────
        if (cfg.type === 'link') {
            // Link fields only have a display input — no hidden <select>
            var inp2 = wrapper.querySelector('input.input-with-feedback');
            if (inp2 && inp2.value && inp2.value.trim()) return inp2.value.trim();
            return '';
        }

        // ── Text / Date / Int / Phone / Email / Textarea ──────────────────────
        var inp3 = wrapper.querySelector('input.input-with-feedback');
        if (inp3 && inp3.value && inp3.value.trim()) return inp3.value.trim();
        var ta = wrapper.querySelector('textarea');
        if (ta && ta.value && ta.value.trim()) return ta.value.trim();
        return '';
    }

    // =========================================================================
    //  WRITE  — set a field silently (no dropdown, no flash)
    // =========================================================================

    function writeField(cfg, val) {
        if (val === '' || val === null || val === undefined) return false;
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return false;

        if (cfg.type === 'check')  return writeCheck(wrapper, val);
        if (cfg.type === 'select') return writeSelect(wrapper, val);
        if (cfg.type === 'link')   return writeLink(wrapper, val);
        return writeText(wrapper, val);
    }

    // ── Checkbox ──────────────────────────────────────────────────────────────
    function writeCheck(wrapper, val) {
        var chk = wrapper.querySelector('input[type="checkbox"]');
        if (!chk) return false;
        var shouldCheck = (val === '1' || val === true || val === 'true');
        if (chk.checked !== shouldCheck) {
            chk.checked = shouldCheck;
            fire(chk, ['change']);
        }
        return true;
    }

    // ── Frappe Select (fixed options — hidden <select> + display input) ───────
    function writeSelect(wrapper, val) {
        var sel = wrapper.querySelector('select');
        var inp = wrapper.querySelector('input.input-with-feedback');
        var matched = false;

        // Step 1 — set hidden <select> (Frappe's source of truth on submit)
        if (sel) {
            for (var i = 0; i < sel.options.length; i++) {
                var o = sel.options[i];
                if (o.value.trim().toLowerCase() === val.toLowerCase() ||
                    o.text.trim().toLowerCase()  === val.toLowerCase()) {
                    sel.selectedIndex = i;
                    matched = true;
                    break;
                }
            }
            if (matched) fire(sel, ['change']);
        }

        // Step 2 — update display input via native setter (bypasses awesomplete)
        if (inp) {
            nativeSet(inp, val);
            fire(inp, ['input', 'change']);
            inp.blur();
            killDropdowns(wrapper);
        }

        return matched || !!inp;
    }

    // ── Frappe Link (autocomplete — only a display input, no hidden <select>) ─
    // Strategy: write to the input via native setter, fire events, then
    // immediately kill any dropdown that opened. This avoids the dropdown flash
    // while still registering the value in Frappe's internal form model.
    function writeLink(wrapper, val) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (!inp) return false;

        // 1. Use native setter — bypasses any Vue/React/awesomplete watcher
        nativeSet(inp, val);

        // 2. Fire input event so Frappe registers the value
        fire(inp, ['input', 'change']);

        // 3. Immediately remove focus & kill dropdown before it renders
        inp.blur();
        killDropdowns(wrapper);

        // 4. Also close at next tick (dropdown opens async in some Frappe versions)
        setTimeout(function () { killDropdowns(wrapper); inp.blur(); }, 0);
        setTimeout(function () { killDropdowns(wrapper); }, 50);
        setTimeout(function () { killDropdowns(wrapper); }, 150);

        return true;
    }

    // ── Text / Date / Textarea ────────────────────────────────────────────────
    function writeText(wrapper, val) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) { inp.value = val; fire(inp, ['input', 'change']); return true; }
        var ta = wrapper.querySelector('textarea');
        if (ta)  { ta.value  = val; fire(ta,  ['input', 'change']); return true; }
        return false;
    }

    // ── Helpers ───────────────────────────────────────────────────────────────
    function nativeSet(inp, val) {
        var desc = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
        if (desc && desc.set) desc.set.call(inp, val);
        else inp.value = val;
    }

    function fire(el, types) {
        types.forEach(function (t) {
            el.dispatchEvent(new Event(t, { bubbles: true }));
        });
    }

    function killDropdowns(wrapper) {
        var root = wrapper || document;
        root.querySelectorAll(
            '.dropdown-menu, .awesomplete > ul, ul.awesomplete, .link-field-popup'
        ).forEach(function (dd) {
            dd.style.display    = 'none';
            dd.style.visibility = 'hidden';
            dd.setAttribute('aria-hidden', 'true');
        });
        var aw = root.querySelector && root.querySelector('.awesomplete');
        if (aw) aw.classList.remove('open');
    }

    // =========================================================================
    //  VERIFY  — confirm a write actually stuck
    // =========================================================================

    function verifyField(cfg, expected) {
        if (cfg.type === 'check') return true; // checkboxes always stick immediately
        var actual = readField(cfg);
        if (!actual) return false;
        return actual.toLowerCase() === expected.toLowerCase();
    }

    // =========================================================================
    //  SAVE DRAFT
    // =========================================================================

    function saveDraft(silent) {
        var fields = discoverFields();
        var userEmail = getUserEmail();
        var draft  = {
            __saved_at   : new Date().toLocaleString(),
            __user_email : userEmail,   // stamped for ownership validation on restore
            __fields     : []
        };

        fields.forEach(function (cfg) {
            var v = readField(cfg);
            draft[cfg.fieldname] = v;
            draft.__fields.push({ fieldname: cfg.fieldname, type: cfg.type });
            if (v) console.log('[Draft] Save:', cfg.fieldname, '(' + cfg.type + ') =', JSON.stringify(v));
        });

        // Always save checkbox even if '0'
        fields.forEach(function (cfg) {
            if (cfg.type === 'check' && draft[cfg.fieldname] === '') {
                draft[cfg.fieldname] = '0';
            }
        });

        var ok = Store.save(draft);
        if (!silent) {
            showToast(ok
                ? '💾 Draft saved at ' + draft.__saved_at
                : '❌ Could not save — storage unavailable',
                ok ? '#16a34a' : '#dc2626'
            );
        }
        console.log('[Draft] Saved ' + fields.length + ' fields (ok=' + ok + ')');
    }

    // =========================================================================
    //  AUTO-SAVE  — 1.5 s debounce after last change
    // =========================================================================

    var _autoTimer = null;
    function scheduleAutoSave() {
        clearTimeout(_autoTimer);
        _autoTimer = setTimeout(function () { saveDraft(true); }, 1500);
    }

    // =========================================================================
    //  RESTORE DRAFT
    // =========================================================================

    function restoreDraft() {
        var draft = Store.load();
        if (!draft) return;

        // ── Ownership check ───────────────────────────────────────────────────
        // Ensure the draft belongs to the current user.
        // The email from the URL/session must match the email saved in the draft.
        var currentEmail = getUserEmail();
        if (currentEmail && draft.__user_email &&
            draft.__user_email.toLowerCase() !== currentEmail.toLowerCase()) {
            console.warn('[Draft] Draft belongs to', draft.__user_email,
                         '— current user is', currentEmail, '— skipping restore.');
            return;
        }

        // Build field config from saved metadata
        var savedFields = (draft.__fields || []).slice();

        // Merge any TYPED_FIELDS not in saved metadata
        var seen = {};
        savedFields.forEach(function (f) { seen[f.fieldname] = true; });
        Object.keys(TYPED_FIELDS).forEach(function (fn) {
            if (!seen[fn] && draft[fn] !== undefined) {
                savedFields.push({ fieldname: fn, type: TYPED_FIELDS[fn] });
            }
        });

        // Only fields that have a non-empty saved value (or '0' for checkboxes)
        var pending = savedFields.filter(function (cfg) {
            var v = draft[cfg.fieldname];
            if (cfg.type === 'check') return v === '1' || v === '0';
            return !!v;
        });

        if (!pending.length) return;

        console.log('[Draft] Restore pending:',
            pending.map(function (f) { return f.fieldname; }));

        var attempts = 0, MAX = 80, toastShown = false;

        function attempt() {
            attempts++;
            var still = [];

            pending.forEach(function (cfg) {
                var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
                if (!wrapper) { still.push(cfg); return; }

                // For selects — wait for options to be populated
                if (cfg.type === 'select') {
                    var sel = wrapper.querySelector('select');
                    var inp = wrapper.querySelector('input.input-with-feedback');
                    if (!((sel && sel.options.length > 1) || inp)) {
                        still.push(cfg); return;
                    }
                }

                writeField(cfg, draft[cfg.fieldname]);

                if (!verifyField(cfg, draft[cfg.fieldname])) {
                    still.push(cfg);
                } else {
                    console.log('[Draft] ✅ Restored:', cfg.fieldname, '->', draft[cfg.fieldname]);
                }
            });

            pending = still;

            if (pending.length === 0) {
                onDone(draft, toastShown); toastShown = true;
            } else if (attempts < MAX) {
                setTimeout(attempt, 100);
            } else {
                console.warn('[Draft] Timed out:',
                    pending.map(function (f) { return f.fieldname; }));
                if (!toastShown) { onDone(draft, false); toastShown = true; }
            }
        }

        attempt();
    }

    function onDone(draft, alreadyShown) {
        setTimeout(updateBtn, 100);
        if (!alreadyShown && draft.__saved_at) {
            showToast('📋 Draft restored from ' + draft.__saved_at, '#2563eb');
        }
    }

    // =========================================================================
    //  PROCEED TO PAY button visibility
    // =========================================================================

    function allFilled() {
        return REQUIRED_FOR_PAY.every(function (fn) {
            return !!readField({ fieldname: fn, type: TYPED_FIELDS[fn] || 'text' });
        });
    }

    function updateBtn() {
        var btn = document.querySelector('button.submit-btn');
        if (btn) btn.classList.toggle('show-pay-btn', allFilled());
    }

    // =========================================================================
    //  TOAST
    // =========================================================================

    function showToast(msg, bg) {
        $('#fle-draft-toast').remove();
        $('<div id="fle-draft-toast"></div>').text(msg).css({
            position: 'fixed', bottom: '28px', right: '28px',
            background: bg || '#16a34a', color: '#fff',
            padding: '11px 20px', borderRadius: '7px',
            fontSize: '13px', fontWeight: '600',
            boxShadow: '0 4px 16px rgba(0,0,0,0.18)',
            zIndex: 999999, opacity: 0, maxWidth: '360px', lineHeight: '1.5'
        }).appendTo('body').animate({ opacity: 1 }, 250);
        setTimeout(function () {
            $('#fle-draft-toast').animate({ opacity: 0 }, 350, function () {
                $(this).remove();
            });
        }, 3500);
    }

    // =========================================================================
    //  DOB VALIDATION
    // =========================================================================

    function isFutureOrToday(val) {
        if (!val) return false;
        var p = val.split('-');
        if (p.length !== 3) return false;
        var d = p[0].length === 4
            ? new Date(+p[0], +p[1]-1, +p[2])
            : new Date(+p[2], +p[0]-1, +p[1]);
        if (!d || isNaN(d.getTime())) return false;
        var t = new Date(); t.setHours(0, 0, 0, 0);
        return d >= t;
    }

    var dobAlertShown = false;

    function showDOBError() {
        if (dobAlertShown) return;
        dobAlertShown = true;
        $('#dob-error-msg').remove();
        $('[data-fieldname="candidate_dob"]').first().after(
            '<div id="dob-error-msg" style="background:#fff2f2;border:1px solid #e74c3c;' +
            'border-left:4px solid #e74c3c;color:#c0392b;padding:10px 14px;border-radius:4px;' +
            'margin-top:6px;font-size:13px;font-weight:500;display:flex;align-items:center;gap:8px;">' +
            '<span style="font-size:16px;">⚠️</span>' +
            'Date of Birth cannot be today or a future date.</div>'
        );
        setTimeout(function () {
            $('#dob-error-msg').fadeOut(400, function () {
                $(this).remove(); dobAlertShown = false;
            });
        }, 4000);
    }

    function clearDOB(inp) {
        inp.value = '';
        $(inp).val('').trigger('change');
        fire(inp, ['input', 'change']);
        setTimeout(updateBtn, 100);
    }

    function restrictDOB() {
        var inp = document.querySelector(
            '[data-fieldname="candidate_dob"] input.input-with-feedback'
        );
        if (!inp || inp.__dob) return;
        inp.__dob = true;
        inp.addEventListener('change', function () {
            if (isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
        inp.addEventListener('blur', function () {
            if (isFutureOrToday(inp.value)) { clearDOB(inp); showDOBError(); }
        });
        inp.addEventListener('keyup', function () {
            if (inp.value.length >= 8 && isFutureOrToday(inp.value)) {
                clearDOB(inp); showDOBError();
            }
        });
    }

    // =========================================================================
    //  ATTACH LISTENERS  (includes checkboxes)
    // =========================================================================

    function attach() {
        document.querySelectorAll(
            '[data-fieldname] input, [data-fieldname] select, [data-fieldname] textarea'
        ).forEach(function (el) {
            if (el.__b) return;
            el.__b = true;
            el.addEventListener('input',  function () { updateBtn(); scheduleAutoSave(); });
            el.addEventListener('change', function () { updateBtn(); scheduleAutoSave(); });
            el.addEventListener('blur',   function () { updateBtn(); scheduleAutoSave(); });
        });
    }

    // =========================================================================
    //  INJECT SAVE AS DRAFT BUTTON
    // =========================================================================

    var draftBtnInjected = false;

    function injectDraftBtn() {
        if (draftBtnInjected) return;

        var $discard = $(
            'button.discard-btn, button[data-label="Discard"], .form-footer .btn-default'
        ).filter(function () {
            return $(this).text().trim().toLowerCase() === 'discard';
        }).first();

        if (!$discard.length) $discard = $('.form-footer, .page-actions').first();
        if (!$discard.length) return;

        $('<button type="button" id="fle-save-draft-btn">💾 Save as Draft</button>')
            .css({
                background: '#fff', color: '#7c3aed',
                border: '1.5px solid #7c3aed', borderRadius: '5px',
                padding: '7px 18px', fontSize: '13px', fontWeight: '600',
                cursor: 'pointer', marginRight: '8px',
                transition: 'background 0.18s, color 0.18s'
            })
            .on('mouseenter', function () { $(this).css({ background: '#7c3aed', color: '#fff' }); })
            .on('mouseleave', function () { $(this).css({ background: '#fff',    color: '#7c3aed' }); })
            .on('click', function () { saveDraft(false); })
            .insertBefore($discard);

        draftBtnInjected = true;
        console.log('[Draft] Button injected.');
    }

    // =========================================================================
    //  DEBUG — type checkFields() in browser console
    // =========================================================================

    window.checkFields = function () {
        console.log('===== LIVE FIELD SCAN =====');
        discoverFields().forEach(function (cfg) {
            var v = readField(cfg);
            console.log((v ? '✅' : '❌'), cfg.fieldname, '(' + cfg.type + ')', '->', JSON.stringify(v));
        });
        console.log('allFilled ->', allFilled());
        console.log('Current user ->', getUserEmail());
        console.log('Draft key    ->', getDraftKey());
        console.log('Stored draft ->', Store.load());
        console.log('===========================');
    };

    // =========================================================================
    //  BOOT
    // =========================================================================

    console.log('[MV] Script loaded');

    restoreDraft(); // immediate — retry loop handles DOM not yet ready

    setInterval(function () {
        restrictDOB(); attach(); updateBtn(); injectDraftBtn();
        var d = document.querySelector('[data-fieldname="candidate_dob"] input.input-with-feedback');
        if (d && d.value && isFutureOrToday(d.value)) { clearDOB(d); showDOBError(); }
    }, 300);

    setTimeout(function () {
        restrictDOB(); attach(); updateBtn(); injectDraftBtn();
        console.log('[MV] Boot complete. Fields:', discoverFields().map(function (f) { return f.fieldname; }));
    }, 2000);

});

